INSERT INTO land_use_types (code, name, group_name, color_hex, is_residential, max_term_text, legal_summary, buildable_guide, conversion_fee_rule) VALUES
('ODT', 'Đất ở tại đô thị', 'Đất phi nông nghiệp', '#ff5c5c', TRUE, 'Ổn định lâu dài', 'Đất để xây dựng nhà ở, các công trình phục vụ đời sống tại đô thị theo quy hoạch.', 'Được phép xây dựng nhà ở kiên cố, tuân thủ giấy phép xây dựng và chỉ giới quy hoạch.', 'Không mất phí chuyển đổi nếu đã là 100% ODT.'),
('ONT', 'Đất ở tại nông thôn', 'Đất phi nông nghiệp', '#ffa3a3', TRUE, 'Ổn định lâu dài', 'Đất để xây dựng nhà ở, công trình phục vụ sinh hoạt tại khu vực nông thôn.', 'Được xây dựng nhà ở nông thôn, mật độ xây dựng theo quy chuẩn khu dân cư nông thôn.', 'Chuyển sang ODT khi lên thị xã/thành phố không thu tiền sử dụng đất nếu đã có sổ đỏ ở lâu dài.'),
('CLN', 'Đất trồng cây lâu năm', 'Đất nông nghiệp', '#d2f5b0', FALSE, '50 năm (gia hạn được)', 'Đất trồng các loại cây trồng một lần sinh trưởng trong nhiều năm.', 'Không được tự ý xây dựng nhà ở kiên cố. Cần xin chuyển mục đích sang đất ở trước khi xây dựng.', 'Chênh lệch giữa giá đất ở và giá đất nông nghiệp theo bảng giá đất tỉnh.'),
('LUC', 'Đất lúa nước còn lại', 'Đất nông nghiệp', '#fef08a', FALSE, '50 năm', 'Đất trồng lúa nước ngoài đất chuyên trồng lúa nước.', 'Không được xây dựng công trình kiên cố.', 'Chuyển mục đích rất nghiêm ngặt, phải có chỉ tiêu phân bổ quy hoạch hàng năm.'),
('LUA', 'Đất chuyên trồng lúa nước', 'Đất nông nghiệp', '#fde047', FALSE, '50 năm', 'Đất trồng từ hai vụ lúa nước trở lên trong năm.', 'Nghiêm cấm tự ý xây dựng công trình, nhà ở.', 'Thẩm quyền cho phép chuyển mục đích thuộc HĐND cấp tỉnh hoặc Thủ tướng Chính phủ.'),
('BHK', 'Đất bằng trồng cây hàng năm khác', 'Đất nông nghiệp', '#fef9c3', FALSE, '50 năm', 'Đất trồng các loại cây rau màu vụ ngắn trên đồng bằng.', 'Chỉ được làm lán trại tạm thời phục vụ canh tác.', 'Được chuyển sang đất ở nếu nằm trong kế hoạch sử dụng đất cấp huyện.'),
('NKH', 'Đất nương rẫy trồng cây hàng năm khác', 'Đất nông nghiệp', '#f5f5dc', FALSE, '50 năm', 'Đất đồi dốc trồng cây hàng năm khác.', 'Không được phép xây dựng công trình nhà ở kiên cố.', 'Chuyển mục đích phải thẩm định chống sạt lở.'),
('RSX', 'Đất rừng sản xuất', 'Đất nông nghiệp', '#86efac', FALSE, '50 năm', 'Đất sử dụng chủ yếu vào mục đích sản xuất gỗ, lâm sản.', 'Được kết hợp du lịch sinh thái dưới tán rừng, tỷ lệ công trình dưới 1-5%.', 'Rất khó chuyển sang đất ở, bảo vệ nghiêm ngặt.'),
('RPH', 'Đất rừng phòng hộ', 'Đất nông nghiệp', '#34d399', FALSE, 'Giao quản lý lâu dài', 'Đất sử dụng nhằm bảo vệ nguồn nước, đất, chống xói mòn.', 'Nghiêm cấm tuyệt đối mọi hành vi xây dựng công trình kiên cố.', 'Không cho phép chuyển sang đất ở cá nhân.'),
('RDD', 'Đất rừng đặc dụng', 'Đất nông nghiệp', '#059669', FALSE, 'Nhà nước bảo tồn', 'Đất vườn quốc gia, khu bảo tồn thiên nhiên.', 'Chỉ phục vụ nghiên cứu khoa học, bảo tồn.', 'Nghiêm cấm chuyển nhượng thương mại.'),
('NTS', 'Đất nuôi trồng thủy sản', 'Đất nông nghiệp', '#7dd3fc', FALSE, '50 năm', 'Đất chuyên dùng để nuôi trồng thủy hải sản nước ngọt, lợ, mặn.', 'Được dựng nhà trông coi tạm thời theo quy định.', 'Chuyển sang đất ở tính bằng 100% tiền sử dụng đất ODT trừ giá trị NTS.'),
('LMU', 'Đất làm muối', 'Đất nông nghiệp', '#e2e8f0', FALSE, '50 năm', 'Đất chuyên sản xuất muối ăn.', 'Không được xây dựng nhà ở.', 'Chuyển mục đích theo quy hoạch kinh tế biển.'),
('NCC', 'Đất nông nghiệp khác', 'Đất nông nghiệp', '#dcfce7', FALSE, '50 năm', 'Nhà kính nông nghiệp, trang trại chăn nuôi.', 'Được xây dựng nhà kính, chuồng trại công nghệ cao.', 'Theo quy hoạch cụm nông nghiệp tập trung.'),
('TSC', 'Đất trụ sở cơ quan', 'Đất phi nông nghiệp', '#93c5fd', FALSE, 'Giao không thu tiền', 'Đất xây dựng cơ quan nhà nước, tổ chức chính trị - xã hội.', 'Xây dựng theo dự án đầu tư công được duyệt.', 'Không giao dịch thương mại tư nhân.'),
('DTS', 'Đất công trình sự nghiệp', 'Đất phi nông nghiệp', '#a7f3d0', FALSE, 'Lâu dài hoặc thuê', 'Đất cơ sở giáo dục, y tế, văn hóa, khoa học.', 'Xây dựng phục vụ mục đích công cộng xã hội.', 'Nhà nước thu hồi hoặc chuyển nhượng theo luật.'),
('CQP', 'Đất quốc phòng', 'Đất phi nông nghiệp', '#b91c1c', FALSE, 'Quốc phòng quản lý', 'Đất dành cho mục đích an ninh quốc phòng, doanh trại.', 'Bộ Quốc phòng phê duyệt công trình.', 'Nghiêm cấm tư nhân mua bán hoặc lấn chiếm.'),
('CAN', 'Đất an ninh', 'Đất phi nông nghiệp', '#dc2626', FALSE, 'Bộ Công an quản lý', 'Đất đồn công an, trại giam, cơ sở an ninh.', 'Bộ Công an phê duyệt.', 'Không thương mại hóa.'),
('SKK', 'Đất khu công nghiệp', 'Đất phi nông nghiệp', '#c084fc', FALSE, 'Theo thời hạn dự án (50-70 năm)', 'Đất tập trung các xí nghiệp, nhà máy sản xuất công nghiệp.', 'Xây dựng nhà xưởng, hạ tầng logistics, văn phòng điều hành.', 'Thuê đất trả tiền hàng năm hoặc một lần.'),
