('SKN', 'Đất cụm công nghiệp', 'Đất phi nông nghiệp', '#d8b4fe', FALSE, '50 năm', 'Đất cụm tiểu thủ công nghiệp làng nghề địa phương.', 'Xây dựng nhà xưởng sản xuất vừa và nhỏ.', 'Thuê đất theo giá ưu đãi của tỉnh.'),
('TMD', 'Đất thương mại, dịch vụ', 'Đất phi nông nghiệp', '#f97316', FALSE, 'Tối đa 50-70 năm', 'Đất xây dựng trung tâm thương mại, khách sạn, resort, shophouse thương mại dịch vụ.', 'Được xây dựng công trình thương mại, kinh doanh dịch vụ du lịch, lưu trú.', 'Được chuyển đổi từ đất ở hoặc đất nông nghiệp trả tiền thuê đất.'),
('SKC', 'Đất cơ sở sản xuất phi nông nghiệp', 'Đất phi nông nghiệp', '#f472b6', FALSE, '50 năm', 'Đất làm cơ sở sản xuất tiểu thủ công nghiệp ngoài KCN.', 'Xây dựng nhà kho, xưởng sản xuất.', 'Chuyển sang ODT phải phù hợp quy hoạch 1/500.'),
('SKS', 'Đất sử dụng cho hoạt động khoáng sản', 'Đất phi nông nghiệp', '#a8a29e', FALSE, 'Theo giấy phép khai thác', 'Đất mỏ đá, quặng, than.', 'Xây dựng trạm khai thác và xử lý quặng.', 'Phải hoàn thổ phục hồi môi trường sau khai thác.'),
('SKX', 'Đất sản xuất vật liệu xây dựng, gốm sứ', 'Đất phi nông nghiệp', '#b45309', FALSE, '50 năm', 'Đất lò gạch ngói, đồ gốm, đá cát sỏi.', 'Nhà xưởng gia công chế biến vật liệu.', 'Tuân thủ bảo vệ môi trường khói bụi.'),
