('DKV', 'Đất khu vui chơi, giải trí công cộng', 'Đất phi nông nghiệp', '#4ade80', FALSE, 'Lâu dài', 'Đất công viên, vườn hoa, quảng trường, bãi tắm công cộng.', 'Xây dựng tiện ích công cộng, cảnh quan sinh thái.', 'Nhà nước đầu tư và vận hành.'),
('CSD', 'Đất cơ sở tôn giáo', 'Đất phi nông nghiệp', '#fbbf24', FALSE, 'Lâu dài', 'Đất chùa, nhà thờ, thánh thất, tu viện.', 'Xây dựng cơ sở thờ tự tín ngưỡng tôn giáo.', 'Nhà nước giao không thu tiền sử dụng đất.'),
