('NTD', 'Đất nghĩa trang, nghĩa địa', 'Đất phi nông nghiệp', '#78716c', FALSE, 'Lâu dài', 'Đất nghĩa trang, nhà tang lễ, lò hỏa táng.', 'Xây dựng hạ tầng nghĩa trang theo quy hoạch chuẩn.', 'Quy hoạch cách ly khu dân cư.'),
('BCS', 'Đất có mặt nước chuyên dùng', 'Đất phi nông nghiệp', '#bae6fd', FALSE, 'Lâu dài', 'Hồ thủy điện, hồ thủy lợi cung cấp nước sinh hoạt.', 'Bảo vệ nghiêm ngặt an toàn đập và nguồn nước.', 'Nghiêm cấm san lấp phân lô.'),
