('DGD', 'Đất xây dựng cơ sở giáo dục và đào tạo', 'Đất phi nông nghiệp', '#c7d2fe', FALSE, 'Lâu dài', 'Trường mầm non, tiểu học, trung học, đại học.', 'Xây dựng lớp học, khuôn viên trường.', 'Giao đất hoặc ưu đãi đầu tư giáo dục.'),
('DTT', 'Đất cơ sở thể dục, thể thao', 'Đất phi nông nghiệp', '#99f6e4', FALSE, 'Lâu dài', 'Sân vận động, nhà thi đấu, trung tâm thể thao.', 'Xây dựng công trình tập luyện thi đấu thể thao.', 'Phục vụ cộng đồng hoặc xã hội hóa.'),
