('DSN', 'Đất danh lam thắng cảnh', 'Đất phi nông nghiệp', '#a7f3d0', FALSE, 'Lâu dài', 'Khu thắng cảnh thiên nhiên sông núi vịnh hang động.', 'Bảo tồn cảnh quan thiên nhiên.', 'Nghiêm cấm phá vỡ địa hình tự nhiên.'),
('DNG', 'Đất ngoại giao', 'Đất phi nông nghiệp', '#fef08a', FALSE, 'Theo hiệp định ngoại giao', 'Đại sứ quán, lãnh sự quán, nhà công vụ viên ngoại giao.', 'Cơ quan ngoại giao quốc tế.', 'Bảo đảm quyền miễn trừ ngoại giao.')
