INSERT INTO legal_articles (slug, title, category, summary, content_html, faqs, tags, word_count) VALUES
('luat-dat-dai-2024-nhung-diem-moi-can-biet', 'Luật Đất Đai 2024: Toàn bộ điểm mới có hiệu lực thi hành', 'phap-ly-quy-hoach', 'Tổng hợp phân tích toàn diện Luật Đất đai số 31/2024/QH15: bỏ khung giá đất, định giá đất theo nguyên tắc thị trường, cấp sổ đỏ cho đất không giấy tờ và bảo vệ quyền lợi người sử dụng đất.', '<p>Luật Đất đai 2024 là bước ngoặt mang tính lịch sử đối với thị trường bất động sản Việt Nam. Một trong những thay đổi đột phá nhất là việc <strong>bỏ khung giá đất</strong> cũ kỹ, thay bằng <strong>bảng giá đất được cập nhật hàng năm</strong> theo sát giá trị giao dịch thực tế trên thị trường.</p><h3>1. Bỏ khung giá đất, xây dựng bảng giá đất hàng năm</h3><p>Từ ngày 01/01/2026, các địa phương trên cả nước sẽ ban hành bảng giá đất mới căn cứ theo nguyên tắc thị trường thay vì bị khống chế bởi khung giá trần của Chính phủ.</p><h3>2. Cấp Giấy chứng nhận quyền sử dụng đất (Sổ đỏ) cho đất không tranh chấp trước 2014</h3><p>Hộ gia đình, cá nhân sử dụng đất ổn định, không tranh chấp trước ngày 01/07/2014 sẽ được xem xét cấp Sổ đỏ với các cơ chế tạo điều kiện thuận lợi tối đa.</p>', '[{"q": "Bảng giá đất mới áp dụng từ khi nào?", "a": "Theo Luật Đất đai 2024, bảng giá đất mới theo nguyên tắc thị trường sẽ chính thức áp dụng từ ngày 01/01/2026 trên toàn quốc."}, {"q": "Đất không có giấy tờ có được cấp sổ đỏ không?", "a": "Có, nếu sử dụng ổn định trước ngày 01/07/2014, không có tranh chấp và được UBND cấp xã xác nhận."}]'::jsonb, ARRAY['luat-dat-dai-2024', 'so-do', 'bang-gia-dat', 'phap-ly-nha-dat'], 1450),
('quy-trinh-thu-tuc-sang-ten-so-do-2025', 'Quy trình và chi phí sang tên Sổ đỏ chi tiết từ A-Z năm 2025 - 2026', 'thu-tuc-mua-ban', 'Hướng dẫn chuẩn hóa quy trình chuyển nhượng bất động sản, công chứng, khai nộp thuế thu nhập cá nhân 2%, lệ phí trước bạ 0.5% và nhận sổ đỏ mới nhanh chóng.', '<p>Thủ tục sang tên Sổ đỏ (đăng ký biến động quyền sử dụng đất) đòi hỏi người mua và người bán tuân thủ nghiêm ngặt trình tự 4 bước quy định tại Bộ Tài nguyên & Môi trường.</p><h3>Bước 1: Lập và công chứng hợp đồng mua bán chuyển nhượng</h3><p>Hai bên có mặt tại văn phòng công chứng với đầy đủ CCCD gắn chip, giấy chứng nhận quyền sử dụng đất và giấy tờ tình trạng hôn nhân.</p><h3>Bước 2: Kê khai nghĩa vụ tài chính tại Chi cục Thuế</h3><p>Khai nộp thuế TNCN (2% giá trị chuyển nhượng) và lệ phí trước bạ (0.5% giá trị bất động sản).</p><h3>Bước 3: Nộp hồ sơ đăng ký biến động tại Văn phòng Đăng ký Đất đai</h3><p>Thời gian xử lý thông thường từ 10 đến 14 ngày làm việc.</p>', '[{"q": "Thuế thu nhập cá nhân khi bán nhà là bao nhiêu?", "a": "Mức thuế TNCN chuyển nhượng bất động sản là 2% tính trên giá trị hợp đồng chuyển nhượng (hoặc bảng giá đất nhà nước nếu giá hợp đồng thấp hơn)."}, {"q": "Ai là người nộp lệ phí trước bạ?", "a": "Theo quy định pháp luật, người nhận chuyển nhượng (người mua) có nghĩa vụ nộp lệ phí trước bạ 0.5%, trừ khi có thỏa thuận khác trong hợp đồng."}]'::jsonb, ARRAY['sang-ten-so-do', 'thue-tncn', 'le-phi-truoc-ba', 'cong-chung'], 1620)
